package hu.boltseged.shipping;

import com.fasterxml.jackson.databind.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;

class DhlPickupPayloadTest {
 @Test void mapsEveryShipmentAndConfiguredAccountToRestPayload(){DhlExpressShippingProvider.DhlProperties properties=new DhlExpressShippingProvider.DhlProperties();properties.setApiBaseUrl("http://localhost");properties.setUsername("user");properties.setPassword("secret");properties.setAccountNumber("123456789");DhlExpressShippingProvider provider=new DhlExpressShippingProvider(properties,new ObjectMapper());ShippingProvider.Address address=new ShippingProvider.Address("Example Kft.","Example User","HU","8200","Veszprem","Example street 1",null,null,"+36201234567","example@example.com");ShippingProvider.Package parcel=new ShippingProvider.Package(new BigDecimal("1.2"),new BigDecimal("20"),new BigDecimal("21"),new BigDecimal("22"));ShippingProvider.PickupRequest request=new ShippingProvider.PickupRequest(LocalDateTime.of(2026,9,21,13,0),address,address,List.of(new ShippingProvider.PickupShipment("P",false,"1234567890",null,null,List.of(parcel)),new ShippingProvider.PickupShipment("U",true,"0987654321",new BigDecimal("50"),"USD",List.of(parcel))),LocalTime.of(17,0),"reception","business","Ring the bell");JsonNode payload=provider.pickupPayload(request);assertEquals("123456789",payload.path("accounts").get(0).path("number").asText());assertEquals(2,payload.path("shipmentDetails").size());assertEquals("P",payload.path("shipmentDetails").get(0).path("productCode").asText());assertFalse(payload.path("shipmentDetails").get(0).has("declaredValue"));assertTrue(payload.path("shipmentDetails").get(1).path("isCustomsDeclarable").asBoolean());assertEquals(new BigDecimal("50"),payload.path("shipmentDetails").get(1).path("declaredValue").decimalValue());assertEquals("USD",payload.path("shipmentDetails").get(1).path("declaredValueCurrency").asText());assertEquals("17:00",payload.path("closeTime").asText());assertEquals("Ring the bell",payload.path("specialInstructions").get(0).path("value").asText());assertTrue(payload.path("plannedPickupDateAndTime").asText().contains("GMT+02:00"));}
}
